using System.Reflection;
using System.Text;
using Microsoft.Extensions.Diagnostics.HealthChecks;
using MimeKit;
using Msg2Eml.Core;

namespace Msg2Eml.Web;

/// <summary>
/// Runs a real micro-conversion of a synthetic <c>.msg</c> embedded in the assembly
/// (generated by <c>tools/gen-fixtures</c>), which exercises MsgReader, MimeKit and the
/// Windows code page provider (requirement 1 of the plan) exactly as a request would.
/// </summary>
public sealed class ConverterHealthCheck(MsgConverter converter) : IHealthCheck
{
    private static readonly byte[] HealthMsg = LoadResource("health.msg");

    public Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context, CancellationToken cancellationToken = default)
    {
        try
        {
            _ = Encoding.GetEncoding(1252);

            var result = converter.Convert(new MemoryStream(HealthMsg, writable: false), cancellationToken);
            using var ms = new MemoryStream(result.Eml, writable: false);
            var mime = MimeMessage.Load(ms, cancellationToken);

            if (mime.Subject != "health" || mime.From.Count != 1 || mime.TextBody?.Trim() != "ok")
                return Task.FromResult(HealthCheckResult.Unhealthy("micro-conversion produced unexpected content"));

            return Task.FromResult(HealthCheckResult.Healthy());
        }
        catch (Exception ex)
        {
            return Task.FromResult(HealthCheckResult.Unhealthy("converter prerequisites missing or micro-conversion failed", ex));
        }
    }

    private static byte[] LoadResource(string name)
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(name)
            ?? throw new InvalidOperationException($"embedded resource '{name}' not found");
        using var ms = new MemoryStream();
        stream.CopyTo(ms);
        return ms.ToArray();
    }
}
